#!/usr/bin/env python3
import base64

path = "/opt/mailoutreach-ai/app.js"
with open(path, "r") as f:
    src = f.read()

# Show Add to CRM when report loaded
src = src.replace(
    '    planStatusMessage.textContent = `Managing report for ${report.companyName}.`;\n  planStatusMessage.className = "status-text info";\n}\n\nasync function loadReport(reportId) {',
    '    planStatusMessage.textContent = `Managing report for ${report.companyName}.`;\n  planStatusMessage.className = "status-text info";\n\n  const addToCrmBtn = document.getElementById("add-to-crm-button");\n  if (addToCrmBtn) addToCrmBtn.style.display = "";\n}\n\nasync function loadReport(reportId) {'
)

# Hide Add to CRM when no report
src = src.replace(
    '    planStatusMessage.textContent = "Generate a report before changing workflow stage.";\n    planStatusMessage.className = "status-text";\n    return;\n  }',
    '    planStatusMessage.textContent = "Generate a report before changing workflow stage.";\n    planStatusMessage.className = "status-text";\n    const addToCrmBtnNull = document.getElementById("add-to-crm-button");\n    if (addToCrmBtnNull) addToCrmBtnNull.style.display = "none";\n    return;\n  }'
)

# Append CRM JS
CRM_B64 = """"""

if "// ── CRM ──" not in src:
    crm_code = base64.b64decode(CRM_B64.encode("ascii")).decode("utf-8")
    src = src.rstrip() + "\n\n" + crm_code

with open(path, "w") as f:
    f.write(src)

print("app.js patched OK")
